@prefix geojson: <https://purl.org/geojson/vocab#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix topo: <https://purl.org/geojson/topo#> .
@prefix toporules: <https://www.ogc.org/rules/topo/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode _:N8317806be83e4abb9d137058af735fc4 ;
            sh:resultMessage "Referenced features must be present within current graph closure for  topological feature." ;
            sh:resultPath topo:relatedFeatures ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Referenced features must be present within current graph closure for  topological feature." ;
                    sh:select """
        prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
        PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
        prefix geojson: <https://purl.org/geojson/vocab#>
        prefix topo: <https://purl.org/geojson/topo#>
        SELECT $this (topo:relatedFeatures as ?path) (?ref as ?value)
        WHERE {
         $this topo:relatedFeatures/rdf:rest*/rdf:first ?ref .
         $this a ?geomtype .
         FILTER ( ?geomtype != geojson:Polygon)
         FILTER NOT EXISTS { ?ref ?p ?o }
        }
""" ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape toporules:testTopoReferencesExist ;
            sh:value <file:///github/workspace/e2> ],
        [ a sh:ValidationResult ;
            sh:focusNode _:N8317806be83e4abb9d137058af735fc4 ;
            sh:resultMessage "Lines topologies must reference points within current graph closure." ;
            sh:resultPath geojson:topology ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Lines topologies must reference points within current graph closure." ;
                    sh:select """
        prefix rdf:     <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
        PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
        prefix geojson: <https://purl.org/geojson/vocab#>
        prefix dct:     <http://purl.org/dc/terms/>
        PREFIX geosparql: <http://www.opengis.net/ont/geosparql#>
        prefix topo: <https://purl.org/geojson/topo#>
        SELECT $this (geojson:topology as ?path) (?ref as ?value)
        WHERE {
         $this topo:relatedFeatures/rdf:rest*/rdf:first ?ref .
         FILTER NOT EXISTS {
             ?ref (geojson:geometry|geosparql:hasGeometry|dct:spatial)/rdf:type geojson:Point }
        }
""" ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape toporules:testTopoLinesReferencePoints ;
            sh:value <file:///github/workspace/e2> ] .

_:Nee417a6e1fd342a88576e5c313bc9f96 rdf:first <file:///github/workspace/e2> ;
